import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import UserStats from '../workspace/app/UserStats'

describe('UserStats', () => {
  it('shows derived active, inactive, and percentage', () => {
    render(
      <UserStats
        users={[
          { id: 1, name: 'John', isActive: true },
          { id: 2, name: 'Jane', isActive: false },
          { id: 3, name: 'Bob', isActive: true },
        ]}
      />
    )

    expect(screen.getByText('Active users count: 2')).toBeTruthy()
    expect(screen.getByText('Inactive users count: 1')).toBeTruthy()
    expect(screen.getByText(/Percentage of active users: 66\.666/)).toBeTruthy()
  })

  it('handles an empty list', () => {
    render(<UserStats users={[]} />)
    expect(screen.getByText('Active users count: 0')).toBeTruthy()
    expect(screen.getByText('Inactive users count: 0')).toBeTruthy()
    expect(screen.getByText('Percentage of active users: 0%')).toBeTruthy()
  })
})

